select 
from crm_wecom_group_reminder
where tenant_id = #{tenantId} and contact_id = #{contactId}
  and rule_id = #{ruleId} and source_ref = #{sourceRef}

select 
from crm_wecom_group_reminder
where tenant_id = #{tenantId}
and contact_id = #{contactId}
and rule_id = #{ruleId}
and status = #{status}
order by due_at desc

select 
from crm_wecom_group_reminder
where tenant_id = #{tenantId}
  and status = 'pending'
  and due_at <= #{now}
  and (claim_lease_until is null or claim_lease_until < #{now})
order by due_at asc
limit #{limit}

