) values (
    #{id}, #{tenantId}, #{contactId}, #{ruleId}, #{sourceRef}, #{chatId}, #{dueAt}, #{status},
    #{payloadJson}, #{renderedText}, #{errcode}, #{errmsg}, #{retryCount}, #{sentAt}, #{skippedReason},
    #{claimLeaseUntil}, #{createTime}, #{updateTime}
)

mapper.update:
update crm_wecom_group_reminder
chat_id = #{chatId}, due_at = #{dueAt}, status = #{status}, payload_json = #{payloadJson}, rendered_text = #{renderedText}, errcode = #{errcode}, errmsg = #{errmsg}, retry_count = #{retryCount}, sent_at = #{sentAt}, skipped_reason = #{skippedReason}, claim_lease_until = #{claimLeaseUntil}, update_time = #{updateTime}
